#import <React/RCTBridgeModule.h>

// Objective-C bridge so React Native's bridge can see the Swift
// VoiceAuthModule class and its @objc-exposed methods. This file (plus a
// bridging header, auto-generated by Xcode when you first add a Swift file
// to an Obj-C project) is the standard way RN projects expose Swift native
// modules - see mobile/README.md for the exact Xcode setup steps.
@interface RCT_EXTERN_MODULE(VoiceAuthModule, NSObject)

RCT_EXTERN_METHOD(requestPermissions:(RCTPromiseResolveBlock)resolve
                  rejecter:(RCTPromiseRejectBlock)reject)

RCT_EXTERN_METHOD(startRecording:(RCTPromiseResolveBlock)resolve
                  rejecter:(RCTPromiseRejectBlock)reject)

RCT_EXTERN_METHOD(stopRecording:(RCTPromiseResolveBlock)resolve
                  rejecter:(RCTPromiseRejectBlock)reject)

RCT_EXTERN_METHOD(authenticateWithDeviceBiometrics:(NSString *)reason
                  resolver:(RCTPromiseResolveBlock)resolve
                  rejecter:(RCTPromiseRejectBlock)reject)

@end
